// Called only by webinarstackai.com/api/billing/webhook, which has already
// verified Stripe's signature and fetched the current state from Stripe.
// The header secret is checked by the Webhook node; this is defence in depth:
// anything not shaped exactly like a billing update is refused.
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const u = body.update && typeof body.update === 'object' ? body.update : {};
const UID = /^[A-Za-z0-9_-]{1,128}$/;
const CUSTOMER = /^(cus_[A-Za-z0-9]{1,250})?$/;
const isoOrEmpty = (v) => v === '' || (typeof v === 'string' && v.length <= 40 && !Number.isNaN(Date.parse(v)));

let update = null;
const base = typeof body.event_id === 'string' && /^evt_[A-Za-z0-9_]{1,250}$/.test(body.event_id) && UID.test(String(u.uid ?? ''));
if (base && u.kind === 'subscription'
  && (u.plan === 'monthly' || u.plan === 'annual')
  && typeof u.status === 'string' && /^[a-z_]{1,40}$/.test(u.status)
  && isoOrEmpty(u.current_period_end)
  && typeof u.cancel_at_period_end === 'boolean'
  && /^sub_[A-Za-z0-9]{1,250}$/.test(String(u.stripe_subscription_id ?? ''))
  && CUSTOMER.test(String(u.stripe_customer_id ?? ''))) {
  update = {
    kind: 'subscription', uid: u.uid, plan: u.plan, status: u.status,
    current_period_end: u.current_period_end, cancel_at_period_end: u.cancel_at_period_end,
    stripe_subscription_id: u.stripe_subscription_id, stripe_customer_id: u.stripe_customer_id || '',
  };
} else if (base && u.kind === 'lifetime'
  && typeof u.active === 'boolean'
  && /^(pi|cs)_[A-Za-z0-9_]{1,250}$/.test(String(u.lifetime_ref ?? ''))
  && CUSTOMER.test(String(u.stripe_customer_id ?? ''))) {
  update = {
    kind: 'lifetime', uid: u.uid, active: u.active,
    lifetime_ref: u.lifetime_ref, stripe_customer_id: u.stripe_customer_id || '',
  };
}

return [{ json: {
  ok: update ? 1 : 0,
  uid: update ? update.uid : '',
  event_id: update ? body.event_id : '',
  event_type: update ? String(body.event_type || '').slice(0, 80) : '',
  update,
} }];

// Applies one billing update to billing/{uid}. The update already reflects
// Stripe's CURRENT state, so it is normally recorded as sent. Two guards stop
// an unrelated event from overwriting a newer truth:
//  - a subscription event never touches an account with Lifetime access;
//  - an old, no-longer-paying subscription never replaces a different one
//    that is still paid.
// A lifetime revoke only applies to the purchase that granted it.
const req = $('Validate Update').first().json;
const u = req.update;
const loaded = $input.first() ? $input.first().json : {};

// A missing document is normal (first purchase). Any other read failure must
// stop here: the site answers Stripe with an error and Stripe retries later,
// instead of a write based on a guessed current state.
if (loaded && loaded.error) {
  const text = JSON.stringify(loaded.error);
  if (!/not.?found|404|NOT_FOUND/i.test(text)) throw new Error('Could not read billing/' + u.uid + ': ' + text.slice(0, 300));
}
const cur = loaded && !loaded.error ? loaded : {};

const str = (v) => (typeof v === 'string' ? v : '');
const ms = (v) => { const t = Date.parse(str(v)); return Number.isFinite(t) ? t : 0; };
const PAID = ['active', 'trialing', 'past_due'];
const paying = (status, end) => PAID.includes(status) && ms(end) > Date.now();

const doc = {
  uid: u.uid,
  plan: ['monthly', 'annual', 'lifetime'].includes(cur.plan) ? cur.plan : 'none',
  status: str(cur.status),
  current_period_end: str(cur.current_period_end),
  cancel_at_period_end: cur.cancel_at_period_end === true,
  stripe_customer_id: str(cur.stripe_customer_id),
  stripe_subscription_id: str(cur.stripe_subscription_id),
  lifetime_ref: str(cur.lifetime_ref),
};

let write = false;
let reason = '';
if (u.kind === 'lifetime') {
  if (u.active) {
    Object.assign(doc, {
      plan: 'lifetime', status: 'lifetime', current_period_end: '', cancel_at_period_end: false,
      lifetime_ref: u.lifetime_ref, stripe_customer_id: u.stripe_customer_id || doc.stripe_customer_id,
    });
    write = true; reason = 'lifetime granted';
  } else if (doc.plan === 'lifetime' && doc.lifetime_ref === u.lifetime_ref) {
    Object.assign(doc, { plan: 'none', status: 'refunded' });
    write = true; reason = 'lifetime revoked (refunded)';
  } else {
    reason = 'inactive lifetime payment that is not the recorded one: ignored';
  }
} else if (doc.plan === 'lifetime') {
  reason = 'account has lifetime access: subscription event ignored';
} else if (doc.stripe_subscription_id && doc.stripe_subscription_id !== u.stripe_subscription_id
  && paying(doc.status, doc.current_period_end) && !paying(u.status, u.current_period_end)) {
  reason = 'a different subscription is still paid: ignored';
} else {
  Object.assign(doc, {
    plan: u.plan, status: u.status, current_period_end: u.current_period_end,
    cancel_at_period_end: u.cancel_at_period_end, stripe_subscription_id: u.stripe_subscription_id,
    stripe_customer_id: u.stripe_customer_id || doc.stripe_customer_id,
  });
  write = true; reason = 'subscription recorded';
}

doc.last_event_id = req.event_id;
doc.updated_at = new Date().toISOString();
return [{ json: { write: write ? 1 : 0, reason, ...doc } }];
